const notice=document.getElementById('accountNotice'),signupForm=document.getElementById('signupForm'),loginForm=document.getElementById('loginForm'),forgotForm=document.getElementById('forgotForm'),resetForm=document.getElementById('resetForm'),forms={signup:signupForm,login:loginForm,forgot:forgotForm,reset:resetForm},pageParams=new URLSearchParams(location.search),inviteToken=pageParams.get('invite'),resetToken=pageParams.get('token'),selectedRole=['contractor','subcontractor'].includes(pageParams.get('role'))?pageParams.get('role'):'';let inviteMessage='';
const views={signup:{title:'Create your account | Trades',kicker:'Built for every market',heading:'One network.<br><em>Two sides.</em><br>Better projects.',body:'Create a company account that can hire subcontractors, find trade work, or do both.',items:['Find and hire trusted trade partners','Bid on nearby jobs and grow your business','Build a reputation contractors can verify']},login:{title:'Sign in | Trades',kicker:'Your work, all in one place',heading:'Pick up where<br><em>you left off.</em>',body:'Sign in to manage opportunities, crews, bids, and the relationships that keep projects moving.',items:['Review new jobs and active bids','Message contractors and trade partners','Keep your company profile up to date']},forgot:{title:'Reset password | Trades',kicker:'Secure account recovery',heading:'Get back to<br><em>good work.</em>',body:'Use a time-limited recovery link to choose a new password and protect your company workspace.',items:['Reset links expire after 30 minutes','Links can only be used once','Existing sessions are signed out after reset']},reset:{title:'Choose a new password | Trades',kicker:'Secure account recovery',heading:'A fresh key<br><em>for your workspace.</em>',body:'Choose a new password to securely regain access to your company account.',items:['Use at least 8 characters','Your reset link works once','Existing sessions will be signed out']}};
function showNotice(message,error=false){notice.textContent=message;notice.hidden=false;notice.classList.toggle('error',error)}function hideNotice(){notice.hidden=true;notice.classList.remove('error')}async function api(path,options={}){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{const response=await fetch(path,{headers:{'Content-Type':'application/json'},signal:controller.signal,...options}),text=await response.text();let data={};try{data=text?JSON.parse(text):{}}catch{throw new Error('The application returned an unexpected response. Please try again.')}if(!response.ok){const error=new Error(data.error||'Request failed');error.status=response.status;error.code=data.code;throw error}return data}catch(error){if(error.name==='AbortError')throw new Error('The application is taking too long to respond. Please try again.');throw error}finally{clearTimeout(timer)}}function signupUrl(){const params=new URLSearchParams();if(inviteToken)params.set('invite',inviteToken);if(selectedRole)params.set('role',selectedRole);return `/signup${params.size?`?${params}`:''}`}
function switchTab(name,{updateUrl=true}={}){const view=views[name]||views.signup;document.querySelectorAll('[data-tab]').forEach(button=>{const active=button.dataset.tab===name;button.classList.toggle('active',active);if(button.getAttribute('role')==='tab')button.setAttribute('aria-selected',String(active))});Object.entries(forms).forEach(([key,form])=>form.hidden=key!==name);document.getElementById('accountTabs').hidden=!['signup','login'].includes(name);document.title=view.title;document.getElementById('storyKicker').textContent=view.kicker;document.getElementById('storyTitle').innerHTML=view.heading;document.getElementById('storyBody').textContent=view.body;document.getElementById('storyList').innerHTML=view.items.map(item=>`<li>${item}</li>`).join('');hideNotice();if(name==='signup'&&inviteMessage)showNotice(inviteMessage);if(updateUrl){const path=name==='signup'?signupUrl():name==='reset'?`/reset-password${resetToken?`?token=${encodeURIComponent(resetToken)}`:''}`:name==='forgot'?'/forgot-password':'/login';history.replaceState({tab:name},'',path)}}
function setSubmitting(form,submitting){const button=form.querySelector('[type="submit"]');if(!button.dataset.label)button.dataset.label=button.textContent;button.disabled=submitting;button.textContent=submitting?button.dataset.loadingLabel:button.dataset.label;form.setAttribute('aria-busy',String(submitting))}
function routeView(){return location.pathname==='/reset-password'?'reset':location.pathname==='/forgot-password'?'forgot':location.pathname==='/login'?'login':'signup'}
document.querySelectorAll('[data-tab]').forEach(button=>button.addEventListener('click',()=>switchTab(button.dataset.tab)));window.addEventListener('popstate',()=>switchTab(routeView(),{updateUrl:false}));if(selectedRole){const capability=signupForm.querySelector(`[name="capability"][value="${selectedRole}"]`);if(capability)capability.checked=true}switchTab(routeView(),{updateUrl:false});if(routeView()==='reset'&&!resetToken)showNotice('This reset link is invalid or incomplete.',true);
if(inviteToken)api(`/api/invites/preview?token=${encodeURIComponent(inviteToken)}`).then(data=>{inviteMessage=`${data.inviterCompany.name} invited you to join their trusted trade network. Create your account to connect automatically.`;if(!signupForm.hidden)showNotice(inviteMessage)}).catch(error=>showNotice(error.message,true));
signupForm.addEventListener('submit',async event=>{event.preventDefault();hideNotice();const form=new FormData(event.currentTarget),capabilities=[...event.currentTarget.querySelectorAll('[name="capability"]:checked')].map(input=>input.value);let succeeded=false;try{if(!capabilities.length)throw new Error('Choose at least one company capability.');setSubmitting(event.currentTarget,true);await api('/api/signup',{method:'POST',body:JSON.stringify({fullName:form.get('fullName'),companyName:form.get('companyName'),city:form.get('city'),state:form.get('state'),trades:String(form.get('trades')||'').split(',').map(value=>value.trim()).filter(Boolean),email:form.get('email'),password:form.get('password'),capabilities,inviteToken})});succeeded=true;location.assign('/dashboard')}catch(error){showNotice(error.message,true)}finally{if(!succeeded)setSubmitting(event.currentTarget,false)}});
loginForm.addEventListener('submit',async event=>{event.preventDefault();hideNotice();const form=new FormData(event.currentTarget);let succeeded=false;try{setSubmitting(event.currentTarget,true);await api('/api/login',{method:'POST',body:JSON.stringify({email:form.get('email'),password:form.get('password')})});succeeded=true;location.assign('/dashboard')}catch(error){showNotice(error.message,true)}finally{if(!succeeded)setSubmitting(event.currentTarget,false)}});
forgotForm.addEventListener('submit',async event=>{event.preventDefault();hideNotice();const form=new FormData(event.currentTarget),preview=document.getElementById('resetPreview');preview.hidden=true;try{setSubmitting(event.currentTarget,true);const result=await api('/api/password/forgot',{method:'POST',body:JSON.stringify({email:form.get('email')})});showNotice(result.message);if(result.resetPath){preview.innerHTML=`<strong>Private alpha reset link</strong>Until email delivery is connected, use this secure link to continue.<a href="${result.resetPath}">Reset password now</a>`;preview.hidden=false}}catch(error){showNotice(error.message,true)}finally{setSubmitting(event.currentTarget,false)}});
resetForm.addEventListener('submit',async event=>{event.preventDefault();hideNotice();const form=new FormData(event.currentTarget),password=form.get('password');let succeeded=false;try{if(password!==form.get('confirmPassword'))throw new Error('Passwords do not match.');setSubmitting(event.currentTarget,true);const result=await api('/api/password/reset',{method:'POST',body:JSON.stringify({token:resetToken,password})});succeeded=true;switchTab('login');showNotice(result.message)}catch(error){showNotice(error.message,true)}finally{if(!succeeded)setSubmitting(event.currentTarget,false)}});
